116|fn race_strategy_row(
117|    race: &RaceContext,
118|    focus_date: NaiveDate,
119|    window_end: NaiveDate,
120|) -> Option<(&str, &str, &str, &str, i32)> {
121|    let race_date = NaiveDate::parse_from_str(&race.date, "%Y-%m-%d").ok()?;
122|    if race_date < focus_date || race_date > window_end {
123|        return None;
124|    }
125|    Some((
126|        &race.date,
127|        &race.priority,
128|        &race.discipline,
129|        &race.name,
130|        (race_date - focus_date).num_days() as i32,
131|    ))
