134|fn infer_packed_focus_date(context: &TrainingContext) -> Option<NaiveDate> {
135|    if let Some(latest_recent_day) = context
136|        .recent_days
137|        .iter()
138|        .filter_map(|day| NaiveDate::parse_from_str(&day.date, "%Y-%m-%d").ok())
139|        .max()
140|    {
141|        return Some(latest_recent_day);
142|    }
143|    if let Some(earliest_upcoming_day) = context
144|        .upcoming_days
145|        .iter()
146|        .filter_map(|day| NaiveDate::parse_from_str(&day.date, "%Y-%m-%d").ok())
147|        .min()
148|    {
149|        return earliest_upcoming_day.pred_opt();
150|    }
151|    if let Some(earliest_projected_day) = context
152|        .projected_days
153|        .iter()
154|        .filter_map(|day| NaiveDate::parse_from_str(&day.date, "%Y-%m-%d").ok())
155|        .min()
156|    {
157|        return earliest_projected_day.pred_opt();
158|    }
159|    chrono::DateTime::from_timestamp(context.generated_at_epoch_seconds, 0)
160|        .map(|timestamp| timestamp.date_naive())
161|}
